    "/api/2.0/online-tables",
]
for ep in create_endpoints:
    try:
        r = requests.post(f"{base_url}{ep}", headers=headers, json=payload)
        results[f"POST {ep}"] = {"status": r.status_code, "body": r.text[:300]}
