import json

host = spark.conf.get("spark.databricks.workspaceUrl")
token = dbutils.notebook.entry_point.getDbutils().notebook().getContext().apiToken().get()

headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}
base_url = f"https://{host}"

results = {}

# Try more possible API paths for Synced Tables
more_endpoints = [
    ("GET", "/api/2.0/preview/synced-tables"),
    ("GET", "/api/2.0/preview/unity-catalog/synced-tables"),
    ("POST", "/api/2.0/preview/synced-tables"),
    ("GET", "/api/3.0/synced-tables"),
    ("GET", "/api/2.0/unity-catalog/tables/workspace.mlpab6c8eeb.predictions7b586d/online"),
